codeExample.code:
// 1. 基础条件类型：根据输入类型选择输出类型
type IsString<T> = T extends string ? "是字符串" : "不是字符串";
type Test1 = IsString<string>; // "是字符串"
type Test2 = IsString<number>; // "不是字符串"

// 2. 使用 infer 提取函数返回类型（模拟内置 ReturnType）
type MyReturnType<T> = T extends (...args: any[]) => infer R ? R : never;
function getUser() {
  return { id: 1, name: "Alice", age: 30 };
}
type User = MyReturnType<typeof getUser>; // { id: number; name: string; age: number }

// 3. 提取 Promise 的解析值类型
function fetchUser(): Promise<{ id: number; name: string }> {
  return Promise.resolve({ id: 1, name: "Alice" });
}
type UnpackPromise<T> = T extends Promise<infer U> ? U : T;
type UserData = UnpackPromise<ReturnType<typeof fetchUser>>; // { id: number; name: string }

// 4. 提取数组元素类型
type UnpackArray<T> = T extends (infer U)[] ? U : T;
type Item = UnpackArray<string[]>; // string

// 5. 递归条件类型：深度提取嵌套 Promise 的值类型
type DeepUnpackPromise<T> =
  T extends Promise<infer U>
    ? DeepUnpackPromise<U> // 如果还是 Promise，就递归解包
    : T; // 如果不是，返回最终类型
type DeepData = DeepUnpackPromise<Promise<Promise<number>>>; // number

codeExample.explanation:
// 示例1：定义了一个接受泛型T的条件类型 IsString。如果T是string的子类型，则结果为字符串字面量类型"是字符串"，否则为"不是字符串"。
// 示例2：MyReturnType 模拟了内置的 ReturnType。它检查T是否是一个函数类型（`(...args: any[]) => ...`），如果是，则用 `infer R` 捕获并返回其返回类型R，否则返回 `never`。
// 示例3：UnpackPromise 检查T是否为 Promise 类型，并用 `infer U` 捕获其内部解析值的类型U，实现“解包”。
// 示例4：UnpackArray 类似，捕获数组的元素类型。
// 示例5：DeepUnpackPromise 是一个递归版本，它会持续解包直到类型不再是 Promise，用于处理嵌套的 Promise。

